use crate::input::*;
use crate::TerminalState;
use std::io::Write;
use termwiz::input::{KeyCodeEncodeModes, KeyboardEncoding};

impl TerminalState {
    fn effective_keyboard_encoding(&self) -> KeyboardEncoding {
        match self
            .screen()
            .keyboard_stack
            .last()
            .unwrap_or(&self.keyboard_encoding)
        {
            KeyboardEncoding::Xterm if self.config.enable_csi_u_key_encoding() => {
                KeyboardEncoding::CsiU
            }
            enc => *enc,
        }
    }

    /// Processes a key event generated by the gui/render layer
    /// that is embedding the Terminal.  This method translates the
    /// keycode into a sequence of bytes to send to the slave end
    /// of the pty via the `Write`-able object provided by the caller.
    fn key_up_down(
        &mut self,
        key: KeyCode,
        mods: KeyModifiers,
        is_down: bool,
    ) -> anyhow::Result<()> {
        let encoding = self.effective_keyboard_encoding();

        let to_send = key.encode(
            mods,
            KeyCodeEncodeModes {
                encoding,
                newline_mode: self.newline_mode,
                application_cursor_keys: self.application_cursor_keys,
                modify_other_keys: self.modify_other_keys,
            },
            is_down,
        )?;

        if to_send.is_empty() {
            return Ok(());
        }

        let label = if is_down { "key_down" } else { "key_up" };
        if self.config.debug_key_events() {
            log::info!("{}: sending {:?}, {:?} {:?}", label, to_send, key, mods);
        } else {
            log::trace!("{}: sending {:?}, {:?} {:?}", label, to_send, key, mods);
        }
        self.writer.write_all(to_send.as_bytes())?;
        self.writer.flush()?;

        Ok(())
    }

    pub fn key_up(&mut self, key: KeyCode, mods: KeyModifiers) -> anyhow::Result<()> {
        self.key_up_down(key, mods, false)
    }

    pub fn key_down(&mut self, key: KeyCode, mods: KeyModifiers) -> anyhow::Result<()> {
        self.key_up_down(key, mods, true)
    }
}

impl TerminalState {
    pub fn semantic_key(&mut self, event: &SemanticKey) -> anyhow::Result<()> {
        anyhow::ensure!(
            (1..=3).contains(&event.phase) && event.modifiers < 256,
            "invalid semantic key"
        );
        let flags = match self.effective_keyboard_encoding() {
            KeyboardEncoding::Kitty(flags) => flags.bits(),
            _ => return self.semantic_legacy(event),
        };
        if flags == 0
            || (flags & 9 == 0
                && matches!(
                    event.key,
                    Some(KeyCode::Enter | KeyCode::Tab | KeyCode::Backspace)
                ))
        {
            return self.semantic_legacy(event);
        }
        let report_events = flags & 2 != 0;
        if event.phase == 3 && !report_events {
            return Ok(());
        }
        let plain_text = matches!(event.key, Some(KeyCode::Char(c)) if !c.is_control())
            && event.modifiers & 0b00111110 == 0
            && flags & 8 == 0;
        if plain_text {
            if event.phase != 3 {
                let text = event.text.clone().unwrap_or_else(|| match event.key {
                    Some(KeyCode::Char(c)) => c.to_string(),
                    _ => unreachable!(),
                });
                self.writer.write_all(text.as_bytes())?;
            }
            return Ok(());
        }
        let (code, suffix) = match event.functional {
            Some(code) => (code, 'u'),
            None => kitty_code(
                event
                    .key
                    .as_ref()
                    .ok_or_else(|| anyhow::anyhow!("missing semantic key identity"))?,
            )?,
        };
        let mut key = code.to_string();
        if flags & 4 != 0 && (event.shifted.is_some() || event.base.is_some()) {
            key.push(':');
            if let Some(shifted) = event.shifted {
                key.push_str(&(shifted as u32).to_string());
            }
            if let Some(base) = event.base {
                key.push(':');
                key.push_str(&(base as u32).to_string());
            }
        }
        let mut encoded = format!("\x1b[{};{}", key, event.modifiers + 1);
        if report_events {
            encoded.push_str(&format!(":{}", event.phase));
        }
        if flags & 16 != 0 && event.phase != 3 {
            if let Some(text) = &event.text {
                if !text.is_empty() {
                    encoded.push(';');
                    encoded.push_str(
                        &text
                            .chars()
                            .map(|c| (c as u32).to_string())
                            .collect::<Vec<_>>()
                            .join(":"),
                    );
                }
            }
        }
        encoded.push(suffix);
        self.writer.write_all(encoded.as_bytes())?;
        Ok(())
    }
    fn semantic_legacy(&mut self, event: &SemanticKey) -> anyhow::Result<()> {
        if event.phase == 3 {
            return Ok(());
        }
        if let Some(code @ 57399..=57416) = event.functional {
            let (plain, application) = match code {
                57399..=57408 => (
                    (b'0' + (code - 57399) as u8) as char,
                    (b'p' + (code - 57399) as u8) as char,
                ),
                57409 => ('.', 'n'),
                57410 => ('/', 'o'),
                57411 => ('*', 'j'),
                57412 => ('-', 'm'),
                57413 => ('+', 'k'),
                57414 => ('\r', 'M'),
                57415 => ('=', 'X'),
                57416 => (',', 'l'),
                _ => unreachable!(),
            };
            if self.application_keypad {
                let encoded = if event.modifiers & 7 == 0 {
                    format!("\x1bO{}", application)
                } else {
                    format!("\x1b[1;{}{}", (event.modifiers & 7) + 1, application)
                };
                self.writer.write_all(encoded.as_bytes())?;
                return Ok(());
            }
            return self.key_down(KeyCode::Char(plain), legacy_modifiers(event.modifiers));
        }
        if let Some(text) = &event.text {
            if event.modifiers & 0b00111110 == 0 {
                self.writer.write_all(text.as_bytes())?;
                return Ok(());
            }
        }
        if let Some(key) = &event.key {
            if matches!(key, KeyCode::Function(25..=35)) {
                return Ok(());
            }
            let key = if event.modifiers & 1 != 0 && matches!(key, KeyCode::Char(_)) {
                event.shifted.map(KeyCode::Char).unwrap_or_else(|| key.clone())
            } else {
                key.clone()
            };
            self.key_down(key, legacy_modifiers(event.modifiers))
        } else {
            // Media and modifier-only events have no legacy terminal bytes.
            Ok(())
        }
    }

    pub fn prediction_eligible(&self) -> bool {
        !self.is_mouse_grabbed()
            && matches!(self.effective_keyboard_encoding(), KeyboardEncoding::Xterm)
    }
}

pub fn legacy_modifiers(bits: u16) -> KeyModifiers {
    let mut mods = KeyModifiers::NONE;
    for (bit, flag) in [
        (1, KeyModifiers::SHIFT),
        (2, KeyModifiers::ALT),
        (4, KeyModifiers::CTRL),
        (8, KeyModifiers::SUPER),
    ] {
        if bits & bit != 0 {
            mods |= flag;
        }
    }
    mods
}

fn kitty_code(key: &KeyCode) -> anyhow::Result<(u32, char)> {
    use KeyCode::*;
    Ok(match key {
        Char(c) => (*c as u32, 'u'),
        Escape => (27, 'u'),
        Enter => (13, 'u'),
        Tab => (9, 'u'),
        Backspace => (127, 'u'),
        UpArrow => (1, 'A'),
        DownArrow => (1, 'B'),
        RightArrow => (1, 'C'),
        LeftArrow => (1, 'D'),
        Home => (1, 'H'),
        End => (1, 'F'),
        Insert => (2, '~'),
        Delete => (3, '~'),
        PageUp => (5, '~'),
        PageDown => (6, '~'),
        Function(1) => (1, 'P'),
        Function(2) => (1, 'Q'),
        Function(3) => (13, '~'),
        Function(4) => (1, 'S'),
        Function(n @ 5..=12) => ([15, 17, 18, 19, 20, 21, 23, 24][(*n - 5) as usize], '~'),
        Function(n @ 13..=35) => (57376 + (*n as u32 - 13), 'u'),
        CapsLock => (57358, 'u'),
        ScrollLock => (57359, 'u'),
        NumLock => (57360, 'u'),
        PrintScreen => (57361, 'u'),
        Pause => (57362, 'u'),
        Menu => (57363, 'u'),
        Shift | LeftShift => (57441, 'u'),
        LeftControl | Control => (57442, 'u'),
        LeftAlt | Alt => (57443, 'u'),
        Super | LeftWindows => (57444, 'u'),
        Hyper => (57445, 'u'),
        Meta => (57446, 'u'),
        RightShift => (57447, 'u'),
        RightControl => (57448, 'u'),
        RightAlt => (57449, 'u'),
        RightWindows => (57450, 'u'),
        _ => anyhow::bail!("key has no supported kitty encoding: {:?}", key),
    })
}
